const nf = (n, d = 1) => Number(n).toLocaleString(LOCALE, {minimumFractionDigits: d, maximumFractionDigits: d});
const isNum = v => v !== null && v !== undefined && v !== '' && Number.isFinite(Number(v));
const level = n => n === null || n === undefined ? 'missing' : n >= PV_CRIT ? 'critical' : n >= PV_WARN ? 'warning' : 'normal';
const pct = n => isNum(n) ? nf(n) + '%' : '—';
const ratio = (u, tot) => isNum(u) && isNum(tot) && Number(tot) > 0 ? Number(u) / Number(tot) * 100 : null;
function bytes(n, d = 1) {
  if (!isNum(n)) return '—';
  let v = Number(n), u = 0; const units = ['B', 'KB', 'MB', 'GB', 'TB', 'PB'];
  while (Math.abs(v) >= 1024 && u < units.length - 1) { v /= 1024; u++; }
  return nf(v, u ? d : 0) + ' ' + units[u];
}
function bps(n) {
  if (!isNum(n)) return '—';
  let v = Number(n), u = 0; const units = ['bps', 'Kbps', 'Mbps', 'Gbps', 'Tbps'];
  while (Math.abs(v) >= 1000 && u < units.length - 1) { v /= 1000; u++; }
  return nf(v, u ? 1 : 0) + ' ' + units[u];
