// ── Acceso a la API de Zabbix por el datasource (POST /resources/zabbix-api) ────────────────
function pvDatasource(context) {
  const targets = context.panelData?.request?.targets || [];
  const uid = targets.map(x => x.datasource?.uid).find(u => u && !String(u).includes('$')) ||
    context.grafana.replaceVariables('${DS_ZABBIX}');
  const sub = context.grafana.replaceVariables('${__appSubUrl}');
  return {uid, base: sub && !sub.includes('$') ? sub : ''};
}
function pvSelectedHosts(context) {
  try {
    const v = JSON.parse(context.grafana.replaceVariables('${host:json}'));
    const list = (Array.isArray(v) ? v : [v]).map(String).filter(x => x && x !== '$__all' && !x.includes('$'));
    return list;
  } catch (e) { return []; }
}
async function pvApi(ds, method, params) {
  const r = await fetch(ds.base + '/api/datasources/uid/' + encodeURIComponent(ds.uid) + '/resources/zabbix-api', {
    method: 'POST', credentials: 'same-origin', headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({method, params}), signal: AbortSignal.timeout(30000)
  });
  if (!r.ok) throw new Error(method + ': HTTP ' + r.status);
  const j = await r.json();
  if (j && j.error) throw new Error(method + ': ' + (j.error.data || j.error.message || 'error'));
  const res = Array.isArray(j) ? j : j?.result;
  if (!Array.isArray(res)) throw new Error(method + ': respuesta inesperada');
  return res;
}

// ── Carga y modelo de datos (compartido por los paneles, caché de 45 s) ──────────────────────
async function pvLoad(context) {
  const ds = pvDatasource(context);
  if (!ds.uid || ds.uid.includes('$')) throw new Error(t('err_ds'));
  const names = pvSelectedHosts(context).sort();
  const cache = globalThis.__lakaPveCache ||= new Map();
  const key = JSON.stringify(['pve-v3', ds.base, ds.uid, names]);
  let entry = cache.get(key);
  if (!entry || Date.now() - entry.created > 45000) {
    entry = {created: Date.now(), promise: pvFetch(ds, names)};
    cache.set(key, entry);
    if (cache.size > 10) cache.delete(cache.keys().next().value);
    entry.promise.catch(() => { if (cache.get(key) === entry) cache.delete(key); });
  }
  const model = await entry.promise;
  model.fetchedAt = entry.created;
  return model;
}

async function pvFetch(ds, names) {
  const hp = {output: ['hostid', 'host', 'name', 'status', 'maintenance_status'], selectParentTemplates: ['host', 'name'],
    filter: {status: 0}};
  if (names.length) hp.filter.name = names;
  const hosts = (await pvApi(ds, 'host.get', hp))
    .filter(h => (h.parentTemplates || []).some(x => /proxmox/i.test(x.host + ' ' + x.name)));
  if (!hosts.length) return pvModel(hosts, [], []);
  const hostids = hosts.map(h => h.hostid);
  const [items, problems] = await Promise.all([
    pvApi(ds, 'item.get', {output: ['itemid', 'hostid', 'name', 'key_', 'lastvalue', 'lastclock', 'value_type', 'state', 'units'],
      selectTags: ['tag', 'value'], hostids, search: {key_: 'proxmox'}, startSearch: true,
      filter: {status: 0, value_type: [0, 1, 3]}}),
    pvApi(ds, 'problem.get', {output: ['eventid', 'name', 'severity', 'clock', 'objectid', 'acknowledged'], hostids,
      recent: false, suppressed: false, sortfield: ['eventid'], sortorder: 'DESC'})
      .catch(() => null),
  ]);
  // problem.get no devuelve el host: se resuelve por el disparador
  let trigHost = new Map();
  if (problems && problems.length) {
    const trig = await pvApi(ds, 'trigger.get', {output: ['triggerid'], triggerids: [...new Set(problems.map(p => p.objectid))],
      selectHosts: ['hostid']}).catch(() => []);
    for (const x of trig) trigHost.set(x.triggerid, (x.hosts || []).map(h => h.hostid));
  }
  const probs = (problems || []).map(p => ({...p, severity: Number(p.severity), hostids: trigHost.get(p.objectid) || []}));
  const model = pvModel(hosts, items, probs);
  model.problemsError = problems === null;
  return model;
}

function pvArgs(key) {
  const i = key.indexOf('[');
  if (i < 0) return [];
  return key.slice(i + 1, key.lastIndexOf(']')).split(',').map(s => s.trim().replace(/^"(.*)"$/, '$1'));
}

function pvModel(hostsRaw, items, problems) {
  const hosts = new Map();
  for (const h of hostsRaw) {
    hosts.set(h.hostid, {hostid: h.hostid, name: h.name || h.host, maintenance: Number(h.maintenance_status) === 1,
      template: null, api: null, quorum: null, cluster: null, nodes: new Map(), storages: new Map(), guests: new Map(),
      problems: problems.filter(p => p.hostids.includes(h.hostid))});
  }
  const node = (h, name) => {
    if (!name) return null;
    if (!h.nodes.has(name)) h.nodes.set(name, {name, host: h});
    return h.nodes.get(name);
  };
  const storage = (h, nodeName, st) => {
    const k = (nodeName || '') + '/' + st;
    if (!h.storages.has(k)) h.storages.set(k, {name: st, node: nodeName || null, shared: !nodeName, host: h});
    return h.storages.get(k);
  };
  const guest = (h, kind, id, nodeName, name) => {
    const k = kind + ':' + id;
    if (!h.guests.has(k)) h.guests.set(k, {kind, id: String(id), node: nodeName, name: name || String(id), host: h, fs: []});
    const g = h.guests.get(k);
    if (nodeName && !g.node) g.node = nodeName;
    if (name && g.name === g.id) g.name = name;
    return g;
  };
  for (const it of items) {
    const h = hosts.get(it.hostid);
    if (!h) continue;
    const key = it.key_, base = key.split('[')[0], a = pvArgs(key);
    const tags = {};
    for (const tg of it.tags || []) if (!(tg.tag in tags)) tags[tg.tag] = tg.value;
    const has = Number(it.lastclock) > 0 && it.lastvalue !== undefined && it.state !== '1';
    const num = has && isNum(it.lastvalue) && Number(it.value_type) !== 1 ? Number(it.lastvalue) : null;
    const str = has ? String(it.lastvalue) : null;
    let m;
    if (base.startsWith('proxmox_ve.')) {
      h.template = 'current';
      if ((m = base.match(/^proxmox_ve\.node\.(qemu|lxc)\.(.+)$/))) {
        const kind = m[1], f = m[2];
        if (f === 'filesystem.utilization') { const g = guest(h, kind, a[1], tags.node, tags[kind]); if (num !== null) g.fs.push({mount: a[2], pct: num}); continue; }
        if (/^(filesystem|network\.(ip|mac|input\.|output\.)|os\.|agent\.version|time)/.test(f) && !['network.input', 'network.output'].includes(f)) continue;
        const g = guest(h, kind, a[1], tags.node, tags[kind]);
        const map = {'cpu.usage': 'cpu', cpu: 'cpu', 'cpu.count': 'vcpu', 'memory.usage': 'memUsed', 'memory.maxmem': 'memTotal',
          'memory.max': 'memTotal', 'memory.utilization': 'memPct', 'disk.usage': 'diskUsed', 'disk.maxdisk': 'diskTotal',
          'disk.utilization': 'diskPct', 'network.input': 'netIn', 'network.output': 'netOut', 'disk.read': 'diskRead',
          'disk.write': 'diskWrite', uptime: 'uptime', status: 'status', agent: 'agent'};
        if (map[f]) g[map[f]] = num;
      } else if ((m = base.match(/^proxmox_ve\.node\.storage\.(used|total|type|utilization)$/))) {
        const s = storage(h, tags.node, a[1]);
        s[{used: 'used', total: 'total', type: 'type', utilization: 'pct'}[m[1]]] = m[1] === 'type' ? str : num;
      } else if ((m = base.match(/^proxmox_ve\.storage\.(used|total|type|utilization)$/))) {
        const s = storage(h, null, a[0]);
        s[{used: 'used', total: 'total', type: 'type', utilization: 'pct'}[m[1]]] = m[1] === 'type' ? str : num;
      } else if ((m = base.match(/^proxmox_ve\.node\.(status|cpu|cpu\.max|mem|maxmem|mem\.utilization|disk|maxdisk|disk\.utilization|uptime|version|ip|subscribe|updates)$/))) {
        const n = node(h, tags.node);
        if (!n) continue;
        const f = {status: 'status', cpu: 'cpu', 'cpu.max': 'cores', mem: 'memUsed', maxmem: 'memTotal', 'mem.utilization': 'memPct',
          disk: 'rootUsed', maxdisk: 'rootTotal', 'disk.utilization': 'rootPct', uptime: 'uptime', version: 'version', ip: 'ip',
          subscribe: 'subscription', updates: 'updates'}[m[1]];
        n[f] = ['version', 'ip', 'subscribe'].includes(m[1]) ? str : num;
        if (m[1] === 'status') n.online = num === 10;
      } else if (base === 'proxmox_ve.node.disk.smart') {
        const n = node(h, tags.node); if (n && num === 0) n.smartFail = (n.smartFail || 0) + 1;
      } else if (base === 'proxmox_ve.cluster.quorum.status') h.quorum = num;
    } else if (base.startsWith('proxmox.')) {
      h.template ||= 'legacy';
      if ((m = base.match(/^proxmox\.(qemu|lxc)\.(.+)$/))) {
        const g = guest(h, m[1], a[0], tags.node, tags.name);
        const map = {cpu: 'cpu', mem: 'memUsed', maxmem: 'memTotal', disk: 'diskUsed', maxdisk: 'diskTotal', netin: 'netIn',
          netout: 'netOut', diskread: 'diskRead', diskwrite: 'diskWrite', uptime: 'uptime'};
        if (m[2] === 'vmstatus') g.status = str;
        else if (map[m[2]]) g[map[m[2]]] = num;
      } else if ((m = base.match(/^proxmox\.node\.(disk|maxdisk|plugintype)$/)) && a.length === 2) {
        const s = storage(h, a[0], a[1]);
        s[{disk: 'used', maxdisk: 'total', plugintype: 'type'}[m[1]]] = m[1] === 'plugintype' ? str : num;
      } else if ((m = base.match(/^proxmox\.node\.(online|cpu|iowait|loadavg|memused|memtotal|rootused|roottotal|swapused|swaptotal|uptime|pveversion|kernelversion|netin|netout)$/))) {
        const n = node(h, a[0] || tags.node);
        if (!n) continue;
        const f = {online: 'status', cpu: 'cpu', iowait: 'iowait', loadavg: 'loadavg', memused: 'memUsed', memtotal: 'memTotal',
          rootused: 'rootUsed', roottotal: 'rootTotal', swapused: 'swapUsed', swaptotal: 'swapTotal', uptime: 'uptime',
          pveversion: 'version', kernelversion: 'kernel', netin: 'netIn', netout: 'netOut'}[m[1]];
        n[f] = ['pveversion', 'kernelversion'].includes(m[1]) ? str : num;
        if (m[1] === 'online') n.online = num === 1;
      } else if (base === 'proxmox.api.available') h.api = num;
      else if (base === 'proxmox.cluster.quorate') { h.quorum = num; h.cluster = a[0]; }
    }
  }
  // Valores derivados
  const all = {hosts: [...hosts.values()], nodes: [], storages: [], guests: []};
  for (const h of all.hosts) {
    for (const n of h.nodes.values()) {
      n.memPct ??= ratio(n.memUsed, n.memTotal);
      n.rootPct ??= ratio(n.rootUsed, n.rootTotal);
      if (n.online === undefined) n.online = null;
      if (n.version) { const v = String(n.version).match(/(\d+\.\d+(?:[.-]\d+)?)/); n.versionShort = v ? v[1] : n.version; }
      n.problems = h.problems.filter(p => p.name.includes('Node [' + n.name + ']') || p.name.includes('[' + n.name + '/'));
      all.nodes.push(n);
    }
    for (const s of h.storages.values()) { s.pct ??= ratio(s.used, s.total); all.storages.push(s); }
    for (const g of h.guests.values()) {
      if (g.node && !h.nodes.has(g.node)) node(h, g.node);
      g.memPct ??= ratio(g.memUsed, g.memTotal);
      if (!isNum(g.memTotal) && isNum(g.memUsed) && isNum(g.memPct) && g.memPct > 0) g.memTotal = g.memUsed / g.memPct * 100;
      g.diskPct ??= ratio(g.diskUsed, g.diskTotal);
      if (g.fs.length) { g.fs.sort((x, y) => y.pct - x.pct); g.fsMax = g.fs[0]; }
      const st = g.status;
      g.running = st === 'running' || st === 2 ? true : st === 'stopped' || st === 1 ? false : isNum(g.uptime) ? Number(g.uptime) > 0 : null;
      g.peak = isNum(g.cpu) || isNum(g.memPct) ? Math.max(isNum(g.cpu) ? g.cpu : -1, isNum(g.memPct) ? g.memPct : -1) : null;
      g.state = g.running === false ? 'stopped' : g.running === null || g.peak === null ? 'missing'
        : g.peak >= PV_CRIT ? 'critical' : g.peak >= PV_WARN ? 'warning' : 'normal';
      all.guests.push(g);
    }
  }
  all.template = all.hosts.some(h => h.template === 'current') ? 'current' : 'legacy';
  all.problems = problems;
  return all;
}

// Enlace al otro dashboard conservando Grupo, Hosts y el rango de tiempo; `nodo` filtra el destino
function pvLink(context, kind, node) {
  const sub = context.grafana.replaceVariables('${__appSubUrl}');
  const base = sub && !sub.includes('$') ? sub : '';
  const vars = ['${group:queryparam}', '${host:queryparam}'].map(v => context.grafana.replaceVariables(v))
    .filter(v => v && !v.includes('${'));
  // Rango relativo (now-1h…) si Grafana lo informa; si no, el rango absoluto actual
  const urlRange = context.grafana.replaceVariables('${__url_time_range}');
  const tr = context.grafana.timeRange;
  const q = [...vars, urlRange && !urlRange.includes('${') ? urlRange
    : 'from=' + Number(tr.from.valueOf()) + '&to=' + Number(tr.to.valueOf())];
  if (node) q.push('var-nodo=' + encodeURIComponent(node));
  return base + '/d/' + PV_UID[kind] + '?' + q.join('&');
}
function pvVar(context, name) {
  const v = context.grafana.replaceVariables('${' + name + '}');
  return v && !v.includes('${') && v !== '$' + name ? v : '';
}

function pvHeader(title, model, extra, nav, tools) {
  const hosts = (model?.hosts || []).filter(h => h.nodes.size || h.storages.size || h.guests.size || (h.api !== null && h.api !== 200)).length;
  const tpl = model ? t(model.template === 'current' ? 'tpl_current' : 'tpl_legacy') : '';
  const age = model ? Date.now() - model.fetchedAt : 0;
  return `<div class="pv-head"><div class="pv-logo">PVE</div><div><h2>${esc(title)}</h2>` +
    `<small>${extra ? extra + ' · ' : ''}${model ? t('hosts_n', hosts) + ' · ' + esc(tpl) : t('loading')}</small></div>` +
    (tools ? `<div class="pv-tools">${tools}</div>` : '') +
    `<div class="pv-nav">${nav || ''}<div class="pv-fresh ${age > 120000 ? 'stale' : ''}" data-fresh="${model?.fetchedAt || ''}">${model ? t('updated', ago(age)) : t('loading')}</div></div></div>`;
}

const PV_FOOTER = `<div class="pv-footer">${t('footer')} · v${PV_VERSION}</div>`;

// ── Panel "Máquinas virtuales Proxmox": resumen, pestañas por estado y tabla ordenable ──
const root = context.element;
const ui = root.pvUi ||= {kind: 'qemu', tab: 'all', search: '', sort: 'state', dir: -1, page: 0, size: 50, node: ''};

// Llegada desde el dashboard de hipervisores con un nodo elegido (variable oculta "nodo")
const varNode = pvVar(context, 'nodo');
if (varNode !== (ui.lastVarNode ?? '')) { ui.lastVarNode = varNode; ui.node = varNode; ui.page = 0; }
const NAV = `<a class="pv-navbtn" href="${esc(pvLink(context, 'hv'))}">${t('go_hv')} →</a>`;

const STATE_RANK = {critical: 4, warning: 3, missing: 2, normal: 1, stopped: 0};
const TABS = [['all', 'tab_all'], ['running', 'tab_running'], ['stopped', 'tab_stopped'], ['warning', 'tab_warning'], ['critical', 'tab_critical']];
const inTab = (g, tab) => tab === 'all' ? true : tab === 'running' ? g.running === true : tab === 'stopped' ? g.running === false : g.state === tab;
const COLS = [
  ['state', 'c_state'], ['name', 'c_vm'], ['node', 'c_node'], ['cpu', 'c_cpu'], ['vcpu', 'c_vcpu'], ['ram', 'c_ram'],
  ['ramtotal', 'c_ramtotal'], ['fs', 'c_fs'], ['disk', 'c_diskio'], ['net', 'c_netio'], ['uptime', 'c_uptime'],
];
const sortValue = (g, k) => ({
  state: STATE_RANK[g.state] * 1000 + (g.peak ?? -1), name: g.name.toLowerCase(), node: (g.node || '').toLowerCase(),
  cpu: g.cpu, vcpu: g.vcpu, ram: g.memPct, ramtotal: g.memTotal, fs: g.kind === 'lxc' ? g.diskPct : g.fsMax?.pct,
  disk: isNum(g.diskRead) || isNum(g.diskWrite) ? (g.diskRead || 0) + (g.diskWrite || 0) : null,
  net: isNum(g.netIn) || isNum(g.netOut) ? (g.netIn || 0) + (g.netOut || 0) : null, uptime: g.uptime,
})[k];

function fsCell(g) {
  if (g.kind === 'lxc') {
    if (!isNum(g.diskPct)) return '<span class="pv-muted">—</span>';
    return `<div class="pv-meter"><div class="top"><small>${bytes(g.diskUsed)} / ${bytes(g.diskTotal)}</small><b>${pct(g.diskPct)}</b></div>` +
      `<div class="pv-track"><span class="${level(g.diskPct)}" style="width:${Math.min(100, g.diskPct)}%"></span></div></div>`;
  }
  if (!g.fsMax) return '<span class="pv-muted">—</span>';
  const title = g.fs.map(f => `${f.mount}: ${pct(f.pct)}`).join('\n');
  return `<div class="pv-meter" title="${esc(title)}"><div class="top"><small>${esc(g.fsMax.mount)}${g.fs.length > 1 ? ' +' + (g.fs.length - 1) : ''}</small><b>${pct(g.fsMax.pct)}</b></div>` +
    `<div class="pv-track"><span class="${level(g.fsMax.pct)}" style="width:${Math.min(100, g.fsMax.pct)}%"></span></div></div>`;
}

function row(g) {
  const stLabel = t('st_' + g.state);
  const off = g.running === false;
  const ramCell = `<div class="pv-meter"><div class="top"><small>${isNum(g.memUsed) ? bytes(g.memUsed) : ''}</small><b class="${off ? 'pv-muted' : ''}">${pct(g.memPct)}</b></div>` +
    `<div class="pv-track"><span class="${level(g.memPct)}" style="width:${isNum(g.memPct) ? Math.min(100, g.memPct) : 0}%"></span></div></div>`;
  const cpuCell = `<div class="pv-meter"><div class="top"><small></small><b class="${off ? 'pv-muted' : ''}">${pct(g.cpu)}</b></div>` +
    `<div class="pv-track"><span class="${level(g.cpu)}" style="width:${isNum(g.cpu) ? Math.min(100, g.cpu) : 0}%"></span></div></div>`;
  const io = (a, b, f, la, lb) => isNum(a) || isNum(b)
    ? `<div class="pv-io"><span class="rd">${la} ${f(a)}</span><span class="wr">${lb} ${f(b)}</span></div>` : '<span class="pv-muted">—</span>';
  const kindLabel = g.kind === 'qemu' ? 'QEMU' : 'LXC';
  return `<tr class="row-${g.state}"><td><span class="pv-badge ${g.state}">${esc(stLabel)}</span></td>` +
    `<td class="pv-name"><b title="${esc(g.host.name)}">${esc(g.name)}</b><small>ID ${esc(g.id)} · ${kindLabel}</small></td>` +
    `<td>${g.node ? `<a class="pv-link" href="${esc(pvLink(context, 'hv', g.node))}" title="${esc(t('see_hv'))}">${esc(g.node)}</a>` : '—'}</td><td>${cpuCell}</td><td>${isNum(g.vcpu) ? nf(g.vcpu, 0) : '<span class="pv-muted">—</span>'}</td>` +
    `<td>${ramCell}</td><td>${isNum(g.memTotal) ? bytes(g.memTotal) : '—'}</td><td>${fsCell(g)}</td>` +
    `<td>${io(g.diskRead, g.diskWrite, Bps, 'L', 'E')}</td><td>${io(g.netIn, g.netOut, bps, '↓', '↑')}</td>` +
    `<td>${off ? `<span class="pv-muted">${t('st_stopped')}</span>` : uptime(g.uptime)}</td></tr>`;
}

function render(model, error) {
  if (!model) {
    root.innerHTML = `<div class="pv">${pvHeader(t('title_vm'), null, '', NAV)}<div class="pv-empty">${error ? esc(error) : t('loading')}</div>${PV_FOOTER}</div>`;
    return;
  }
  const kind = ui.kind;
  const base = model.guests.filter(g => g.kind === kind && (!ui.node || g.node === ui.node));
  const count = tab => base.filter(g => inTab(g, tab)).length;
  const kindName = t(kind === 'qemu' ? 'machines_qemu' : 'machines_lxc');
  const card = (cls, label, value, sub) => `<div class="pv-card ${cls}"><span>${label}</span><b>${value}</b><small>${sub}</small></div>`;
  const summary = [
    card('info', t('k_total'), base.length, kindName),
    card('normal', t('k_running'), count('running'), t('k_running_sub')),
    card('missing', t('k_stopped'), count('stopped'), t('k_stopped_sub')),
    card('warning', t('k_warning'), count('warning'), t('k_warning_sub', PV_WARN)),
    card('critical', t('k_critical'), count('critical'), t('k_critical_sub', PV_CRIT)),
    card('missing', t('k_missing'), base.filter(g => g.state === 'missing').length, t('k_missing_sub')),
  ].join('');
  const q = ui.search.trim().toLowerCase();
  const rows = base.filter(g => inTab(g, ui.tab) &&
    (!q || [g.name, g.id, g.node, g.host.name].join(' ').toLowerCase().includes(q)));
  rows.sort((a, b) => {
    const x = sortValue(a, ui.sort), y = sortValue(b, ui.sort);
    const xn = x === null || x === undefined, yn = y === null || y === undefined;
    if (xn !== yn) return xn ? 1 : -1;
    let c = xn ? 0 : ui.dir * (typeof x === 'number' && typeof y === 'number' ? x - y : String(x).localeCompare(String(y), undefined, {numeric: true}));
    if (!c) c = (b.peak ?? -1) - (a.peak ?? -1);
    return c || a.name.localeCompare(b.name, undefined, {numeric: true});
  });
  const size = ui.size || rows.length || 1;
  const pages = Math.max(1, Math.ceil(rows.length / size));
  ui.page = Math.min(ui.page, pages - 1);
  const from = ui.page * size, view = rows.slice(from, from + size);
  const tabs = TABS.map(([k, l]) => `<button type="button" data-tab="${k}" class="${ui.tab === k ? 'active' : ''} ${k === 'warning' ? 'warn' : k === 'critical' ? 'crit' : ''}">${t(l)}<span class="n">${count(k)}</span></button>`).join('');
  const kinds = [['qemu', 'QEMU'], ['lxc', 'LXC']].map(([k, l]) => `<button type="button" data-kind="${k}" class="${ui.kind === k ? 'active' : ''}">${l} <span class="n">${model.guests.filter(g => g.kind === k).length}</span></button>`).join('');
  const sizes = [25, 50, 100, 0].map(n => `<button type="button" data-size="${n}" class="${ui.size === n ? 'active' : ''}">${n || t('all_rows')}</button>`).join('');
  const head = COLS.map(([k, l]) => `<th data-sort="${k}" class="${ui.sort === k ? 'sorted' : ''}">${t(l)}<i>${ui.sort === k ? (ui.dir < 0 ? '▼' : '▲') : '↕'}</i></th>`).join('');
  const nodeChip = ui.node ? ` <button type="button" data-clearnode="1" title="${esc(t('clear_node'))}">${t('c_node')}: ${esc(ui.node)} ✕</button>` : '';
  const sub = `<b>${t(kind === 'qemu' ? 'sec_qemu' : 'sec_lxc')}</b> · ${t('running_of', count('running'), base.length)}`;
  const tools = `<input class="pv-search" placeholder="${esc(t('search_vm'))}" value="${esc(ui.search)}">` +
    `<span class="pv-count">${rows.length ? `${from + 1}–${from + view.length}` : 0} ${t('of')} ${rows.length}</span>` +
    `<div class="pv-group">${kinds}</div><div class="pv-group">${tabs}</div>` +
    `<div class="pv-group" title="${esc(t('page_size'))}"><span class="pv-label">${t('show')}</span>${sizes}</div>${nodeChip}`;
  root.innerHTML = `<div class="pv">${pvHeader(t('title_vm'), model, sub, NAV, tools)}<div class="pv-summary">${summary}</div>` +
    `<div class="pv-scroll"><table><thead><tr>${head}</tr></thead><tbody>${view.map(row).join('') ||
      `<tr><td colspan="${COLS.length}" class="pv-empty">${base.length ? t('no_match') : t('no_guests')}</td></tr>`}</tbody></table></div>` +
    (pages > 1 ? `<div class="pv-pager"><button type="button" data-page="-1" ${ui.page ? '' : 'disabled'}>‹</button>${t('page_of', ui.page + 1, pages)}<button type="button" data-page="1" ${ui.page < pages - 1 ? '' : 'disabled'}>›</button></div>` : '') +
    `<div class="pv-note">${t('note_vm', PV_WARN, PV_CRIT)}</div>${PV_FOOTER}</div>`;
  if (ui.focus) { const i = root.querySelector('.pv-search'); i.focus(); i.setSelectionRange(i.value.length, i.value.length); }
}

if (root.pvClick) root.removeEventListener('click', root.pvClick, true);
if (root.pvInput) root.removeEventListener('input', root.pvInput, true);
if (root.pvChange) root.removeEventListener('change', root.pvChange, true);
root.pvClick = e => {
  const tab = e.target.closest?.('[data-tab]'), kind = e.target.closest?.('[data-kind]'), th = e.target.closest?.('th[data-sort]');
  const pg = e.target.closest?.('[data-page]'), cn = e.target.closest?.('[data-clearnode]'), sz = e.target.closest?.('[data-size]');
  if (tab) { ui.tab = tab.dataset.tab; ui.page = 0; }
  else if (kind) { ui.kind = kind.dataset.kind; ui.page = 0; }
  else if (th) { const k = th.dataset.sort; ui.dir = ui.sort === k ? -ui.dir : (['name', 'node'].includes(k) ? 1 : -1); ui.sort = k; }
  else if (pg) { ui.page = Math.max(0, ui.page + Number(pg.dataset.page)); }
  else if (cn) { ui.node = ''; ui.page = 0; }
  else if (sz) { ui.size = Number(sz.dataset.size); ui.page = 0; }
  else return;
  e.preventDefault(); ui.focus = false; render(root.pvModel);
};
root.pvInput = e => { if (!e.target.matches?.('.pv-search')) return; ui.search = e.target.value; ui.page = 0; ui.focus = true; render(root.pvModel); };
root.pvChange = () => {};
root.addEventListener('click', root.pvClick, true);
root.addEventListener('input', root.pvInput, true);
root.addEventListener('change', root.pvChange, true);

render(root.pvModel || null);
pvLoad(context).then(m => { root.pvModel = m; render(m); })
  .catch(err => { console.warn('LAKA Proxmox:', err); if (!root.pvModel) render(null, t('err_load') + ' ' + err.message); });

