.pv-search::placeholder{color:#91a0b5;opacity:1}.pv-search:focus{outline:2px solid #5794f2;outline-offset:1px}
.pv-count{border-radius:16px;background:#2b313b;padding:5px 9px;font-size:11px}
.pv-filters{margin-left:auto;display:flex;gap:5px;flex-wrap:wrap;align-items:center}
.pv button,.pv select{border:1px solid #424a56;background:#252a32;color:#d8dee9;border-radius:4px;padding:6px 10px;cursor:pointer;font-size:11px}
.pv button:hover{background:#333c49;border-color:#697c97}
.pv button.active{background:#e8edf5;border-color:#e8edf5;color:#111}
.pv button .n{display:inline-block;margin-left:6px;border-radius:9px;padding:0 6px;background:#333b47;color:#d8dee9;font-size:10px}
.pv button.active .n{background:#c8ced8;color:#111}
.pv button.warn .n{background:#5a4520;color:#ffc857}.pv button.crit .n{background:#5a2433;color:#ff8ca3}
.pv-section{display:flex;align-items:baseline;gap:10px;margin:4px 0 10px}
.pv-section h3{margin:0;font-size:14px;color:#e8edf5}.pv-section small{color:#9aa9ba;font-size:11px}
.pv-type{display:flex;gap:4px;margin-left:12px}
.pv-scroll{overflow:auto;border:1px solid #353c46;border-radius:5px;scrollbar-color:#4b5667 #181b1f}
.pv table{width:100%;border-collapse:collapse;white-space:nowrap}
.pv th{padding:10px;background:#242b35;text-align:left;font-size:10px;font-weight:700;color:#b9c6d9;cursor:pointer;position:sticky;top:0;z-index:1;letter-spacing:.4px}
.pv th i{font-style:normal;margin-left:4px;opacity:.5}.pv th.sorted{color:#6ae9d1}.pv th.sorted i{opacity:1}
.pv td{padding:7px 10px;border-top:1px solid #303641;vertical-align:middle;line-height:1.3}
.pv tr:hover td{background:#222d38}
.pv tr.row-critical td:first-child{box-shadow:inset 3px 0 #ff6685}.pv tr.row-warning td:first-child{box-shadow:inset 3px 0 #f5b942}
.pv-badge{display:inline-block;border-radius:10px;padding:3px 9px;font-size:10px;font-weight:700}
.pv-badge.critical{background:#40232f;color:#ff8ca3}.pv-badge.warning{background:#40331e;color:#ffc857}
.pv-badge.normal{background:#183b35;color:#3de0b9}.pv-badge.stopped{background:#2b313b;color:#aab6c6}
.pv-badge.missing{background:#2b313b;color:#9ba7b7}.pv-badge.online{background:#183b35;color:#3de0b9}
.pv-badge.offline{background:#40232f;color:#ff8ca3}.pv-badge.info{background:#1d3550;color:#75baff}
.pv-name{min-width:200px;max-width:320px}
.pv-name a,.pv-name b{color:#6cb6ff;font-weight:700;text-decoration:none;cursor:pointer}
.pv-name a:hover{text-decoration:underline}
.pv-name small,.pv-sub{display:block;margin-top:3px;color:#9aa9ba;font-size:10px}
.pv-meter{min-width:150px}
.pv-meter .top{display:flex;justify-content:space-between;align-items:baseline;gap:8px}
.pv-meter .top small{color:#9aa9ba;font-size:10px}.pv-meter .top b{font-size:12px}
.pv-track{height:5px;background:#2c333d;border-radius:3px;overflow:hidden;margin-top:4px}
.pv-track span{display:block;height:100%;background:#3dbb84}
.pv-track span.warning{background:#f5b942}.pv-track span.critical{background:#ff5f7e}
.pv-io span{display:block;font-size:11px;margin:1px 0}
.pv-io .rd{color:#66d4f5}.pv-io .wr{color:#b9a0ff}
.pv-muted{color:#7f8ea3}
.pv-pager{display:flex;gap:8px;align-items:center;justify-content:flex-end;margin-top:8px;font-size:11px;color:#9aa9ba}
.pv-note{margin-top:10px;font-size:10px;color:#9aa9ba;line-height:1.5}
.pv-footer{margin-top:8px;text-align:right;font-size:10px;color:#7f8ea3}
.pv-empty{padding:18px;text-align:center;color:#9aa9ba}
/* Hipervisores */
.pv-hosts{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,520px),1fr));gap:14px}
.pv-host{background:#1d2127;border:1px solid #353b45;border-radius:8px;padding:12px}
.pv-host-head{display:flex;align-items:center;gap:10px;margin-bottom:10px}
.pv-host-head .pv-logo{padding:6px 5px;font-size:10px}
.pv-host-head h4{margin:0;font-size:14px;color:#e8edf5}
.pv-chips{margin-left:auto;display:flex;gap:5px;align-items:center}
.pv-sev{display:inline-block;min-width:20px;text-align:center;border-radius:4px;padding:2px 5px;font-size:10px;font-weight:700;color:#111}
.pv-node{background:#20242b;border:1px solid #303641;border-radius:6px;padding:10px;margin-bottom:10px}
.pv-node-head{display:flex;align-items:center;gap:8px}
.pv-node-head a{color:#6cb6ff;font-weight:700;font-size:13px;text-decoration:none;cursor:pointer}
.pv-node-head a:hover{text-decoration:underline}
.pv-dot{width:8px;height:8px;border-radius:50%;background:#3de0b9;display:inline-block}.pv-dot.off{background:#ff6b89}
.pv-node-meta{color:#9aa9ba;font-size:11px;margin:4px 0 8px}.pv-node-meta b{color:#d8dee9;font-weight:700}
.pv-gauges{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}
.pv-gauge{background:#181b1f;border-radius:6px;padding:6px 4px 8px;text-align:center}
.pv-gauge svg{width:100%;max-width:220px;height:auto;display:block;margin:0 auto}
.pv-gauge span{display:block;font-size:10px;font-weight:700;letter-spacing:.5px;color:#b9c6d9;margin-top:2px;text-transform:uppercase}
.pv-gauge small{display:block;font-size:10px;color:#9aa9ba;margin-top:2px}
.pv-storage{background:#20242b;border:1px solid #303641;border-radius:6px;padding:10px}
.pv-storage-head{display:flex;justify-content:space-between;font-size:10px;font-weight:700;letter-spacing:.5px;color:#b9c6d9;margin-bottom:6px}
.pv-storage-head small{font-weight:400;color:#9aa9ba;letter-spacing:0}
.pv-st{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,1.6fr) 52px;gap:10px;align-items:center;padding:5px 0;border-top:1px solid #2a3039}
.pv-st:first-of-type{border-top:0}
.pv-st b{font-size:11px;color:#e8edf5;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pv-st b small{font-weight:400;color:#7f8ea3;margin-left:5px}
.pv-st em{font-style:normal;font-size:10px;color:#9aa9ba}
.pv-st strong{text-align:right;font-size:11px}
.pv-more{width:100%;margin-top:6px;border-style:dashed !important;background:transparent !important}
@media(max-width:900px){.pv-hosts{grid-template-columns:1fr}.pv-filters{margin-left:0}}
.pv-node-head a.pv-minibtn{font-size:10px;font-weight:400;padding:3px 8px}
